  'user.verification-code.required': 'الرجاء إدخال رمز التحقق!',
  'user.captcha.required': 'الرجاء إدخال رمز التحقق الرسومي!',
  'user.login.infos': 'NEXTPlutus هي أداة مساعدة لتحليل الأسهم متعددة الوكلاء تعمل بالذكاء الاصطناعي ولا تتمتع بمؤهلات استشارية في مجال الاستثمار في الأوراق المالية. يتم إنشاء جميع نتائج التحليل والدرجات والآراء المرجعية في المنصة تلقائيًا بواسطة الذكاء الاصطناعي استنادًا إلى البيانات التاريخية وتستخدم فقط للتعلم والبحث والتبادل الفني، ولا تشكل أي نصيحة استثمارية أو أساس لصنع القرار. ينطوي الاستثمار في الأسهم على مخاطر مختلفة مثل مخاطر السوق، ومخاطر السيولة، ومخاطر السياسة، وما إلى ذلك، مما قد يؤدي إلى خسارة رأس المال. يجب على المستخدمين اتخاذ قرارات مستقلة بناءً على قدرتهم على تحمل المخاطر، ويجب أن يتحمل المستخدم أي سلوك استثماري وعواقب تنشأ عن استخدام هذه الأداة. السوق محفوف بالمخاطر والاستثمار يحتاج إلى الحذر.',
  'user.login.tab-login-web3': 'تسجيل الدخول إلى Web3',
  'user.login.web3.tip': 'تسجيل الدخول بالتوقيع باستخدام المحفظة',
