  'user.login.subtitle': 'رؤى كمية مدفوعة في الأسواق العالمية',
  'user.login.legal.title': 'إخلاء المسؤولية القانونية',
  'user.login.legal.view': 'عرض إخلاء المسؤولية القانونية',
  'user.login.legal.collapse': 'طي إخلاء المسؤولية القانونية',
  'user.login.legal.agree': 'لقد قرأت ووافقت على إخلاء المسؤولية القانونية',
  'user.login.legal.required': 'يرجى قراءة والتحقق من إخلاء المسؤولية القانونية أولا',
  'user.login.legal.content': 'NEXTPlutus هي أداة مساعدة لتحليل الأسهم متعددة الوكلاء تعمل بالذكاء الاصطناعي ولا تتمتع بمؤهلات استشارية في مجال الاستثمار في الأوراق المالية. يتم إنشاء جميع نتائج التحليل والتقييمات والآراء المرجعية في المنصة تلقائيًا بواسطة الذكاء الاصطناعي استنادًا إلى البيانات التاريخية وتستخدم فقط للتعلم والبحث والتبادل الفني، ولا تشكل أي نصيحة استثمارية أو أساس لصنع القرار. ينطوي الاستثمار في الأسهم على مخاطر مختلفة مثل مخاطر السوق، ومخاطر السيولة، ومخاطر السياسة، وما إلى ذلك، مما قد يؤدي إلى خسارة رأس المال. يجب على المستخدمين اتخاذ قرارات مستقلة بناءً على قدرتهم على تحمل المخاطر، ويجب أن يتحمل المستخدم أي سلوك استثماري وعواقب تنشأ عن استخدام هذه الأداة. السوق محفوف بالمخاطر والاستثمار يحتاج إلى الحذر.',
  'user.login.privacy.title': 'سياسة خصوصية المستخدم',
  'user.login.privacy.view': 'عرض سياسة خصوصية المستخدم',
  'user.login.privacy.collapse': 'إغلاق شروط خصوصية المستخدم',
  'user.login.privacy.content': 'نحن نقدر خصوصيتك وحماية البيانات. 1) نطاق التجميع: يتم جمع المعلومات المطلوبة لتنفيذ الوظيفة فقط (مثل البريد الإلكتروني ورقم الهاتف المحمول ورمز المنطقة وعنوان محفظة Web3) والسجلات الضرورية ومعلومات الجهاز. 2) الغرض من الاستخدام: لتسجيل الدخول إلى الحساب والتحقق من الأمان وتوفير وظيفة الخدمة واستكشاف الأخطاء وإصلاحها ومتطلبات الامتثال. 3) التخزين والأمان: يتم تشفير البيانات وتخزينها، ويتم اتخاذ الأذونات اللازمة وإجراءات التحكم في الوصول لمحاولة منع الوصول غير المصرح به أو الكشف عنها أو فقدانها. 4) المشاركة مع أطراف ثالثة: ما لم يكن ذلك مطلوبًا بموجب القوانين واللوائح أو ضروريًا لأداء الخدمات، لن تتم مشاركة معلوماتك الشخصية مع أطراف ثالثة؛ إذا كانت هناك خدمات تابعة لجهات خارجية (مثل المحافظ ومقدمي خدمات الرسائل النصية القصيرة)، فلن تتم معالجتها إلا إلى الحد الأدنى اللازم لتنفيذ الوظيفة. 5) ملفات تعريف الارتباط/التخزين المحلي: تُستخدم لحالة تسجيل الدخول وصيانة الجلسة الضرورية (مثل الرموز المميزة، PHPSESSID)، ويمكنك مسحها أو تقييدها في المتصفح. 6) الحقوق الشخصية: يمكنك ممارسة حقوقك في الاستفسار والتصحيح والحذف وسحب الموافقة وما إلى ذلك وفقًا للقوانين واللوائح. 7) التغييرات والإشعارات: عند تحديث هذه الشروط، سيتم عرضها بشكل بارز على الصفحة. من خلال الاستمرار في استخدام هذه الخدمة، يعتبر أنك قد قرأت المحتوى المحدث ووافقت عليه. إذا كنت لا توافق على هذه الشروط أو أي تحديثات لها، فيرجى التوقف عن استخدام الخدمة والاتصال بنا.',
  'user.login.legal.agreeButton': 'إذن',

