  'fastAnalysis.indicatorsProSubtitle': 'متوافق مع MarketDataCollector._calculate_indicators في الخلفية (نمط السائد): RSI(14) يتم تنعيمه بطريقة Wilder. MACD(12,26,9) يستخدم EMAs مبدئة بـ SMA على الأسعار الإغلاق؛ DIF من الشمعة 26 فصاعدًا؛ DEA = EMA9 لسلسلة DIF (~34+ شمعة لخط إشارة كامل). المتوسطات المتحركة هي SMAs. المحور يستخدم أعلى/أدنى/إغلاق الشمعة السابقة. التأرجح = أعلى/أدنى 20 شمعة. بولينجر = SMA(20) ± 2×σ المجتمع؛ المستويات المجمعة تستخدم BB_upper/BB_lower. ATR(14) هو Wilder، متسلسل إلى أحدث شمعة. راجع docs/INDICATOR_DEFINITIONS_CN.md لنسبة الحجم وموقع النطاق.',
