  "dashboard.indicator.backtest.executionAssumptions.bodyScriptStandard": "اختبار استراتيجية البرنامج النصي: يتم تشغيل on_bar على كل شمعة مغلقة ضمن الإطار الزمني للاستراتيجية؛ ويتم تنفيذ أوامر البرنامج النصي عند فتح الشمعة التالية افتراضيًا (مع إضافة الانزلاق/الرسوم). هذا ليس مفتاح تبديل الوضع الصارم/غير الصارم للمؤشر، بل هو مسار إعادة تشغيل البرنامج النصي القياسي.",
