  "dashboard.indicator.guide.section1.dataNote": "يتم ترتيب فهرس البيانات من الأقدم إلى الأحدث (0 هو أقدم البيانات، والصف الأخير هو أحدث البيانات).",
  "dashboard.indicator.guide.section1.env": "يتم تشغيل التعليمات البرمجية الخاصة بك في بيئة بايثون المستندة إلى المتصفح (Pyodide).",
