  "dashboard.indicator.guide.section1.libsDesc": "يتم استيراد المكتبات التالية افتراضيًا، فلا حاجة لاستيرادها مرة أخرى:",
  "dashboard.indicator.guide.section1.libsList": "<code>pandas</code> (pd), <code>numpy</code> (np), <code>math</code>, <code>json</code>",
  "dashboard.indicator.guide.section1.title": "1. بيئة التشغيل والمتغيرات المُعرّفة مسبقًا",
  "dashboard.indicator.guide.section2.desc": "يمكنك تعريف المتغيرات كمعاملات في بداية الكود. سيحاول النظام تحليل عبارات مثل <code>variable = value</code> كمعاملات قابلة للتعديل.",
