  "dashboard.indicator.guide.section2.title": "2. تعريف المعلمات",
  "dashboard.indicator.guide.section3.backtestBuySignal": "<code>df['buy_signal']</code> - سلسلة منطقية، القيمة True تشير إلى إشارة شراء",
  "dashboard.indicator.guide.section3.backtestExample": "Example:",
  "dashboard.indicator.guide.section3.backtestExampleCode": "<code>df['buy_signal'] = condition_buy</code><br/><code>df['sell_signal'] = condition_sell</code>",
  "dashboard.indicator.guide.section3.backtestNote": "ملاحظة: حتى إذا قمت بتعيين <code>output.signals</code> فقط لعرض الرسم البياني، فيجب عليك تعيين هذين العمودين لتمكين الاختبار الخلفي.",
  "dashboard.indicator.guide.section3.backtestRequired": "<strong>مطلوب للاختبار الخلفي:</strong>",
  "dashboard.indicator.guide.section3.backtestSellSignal": "<code>df['sell_signal']</code> - سلسلة منطقية، القيمة True تشير إلى إشارة بيع",
  "dashboard.indicator.guide.section3.desc": "إذا كنت تريد أن يدعم مؤشرك الاختبار الخلفي، فعليك <strong>must</strong> تعيين العمودين التاليين في التعليمات البرمجية الخاصة بك:",
  "dashboard.indicator.guide.section3.title": "3. إعداد إشارة الاختبار الخلفي (مهم!)",
  "dashboard.indicator.guide.section4.calculatedVars": "<code>calculatedVars</code> - المتغيرات المحسوبة (اختياري، لعرض معلومات إضافية)",
  "dashboard.indicator.guide.section4.desc": "في نهاية تنفيذ التعليمات البرمجية، يجب عليك تعريف قاموس باسم <code>output</code> لإخبار الرسم البياني بكيفية عرض النتائج.",
  "dashboard.indicator.guide.section4.fields": "يحتوي قاموس <code>output</code> على الحقول التالية:",
  "dashboard.indicator.guide.section4.name": "<code>name</code> - اسم المؤشر (اختياري)",
  "dashboard.indicator.guide.section4.plots": "<code>plots</code> - لرسم الخطوط (مثل المتوسطات المتحركة، مؤشر القوة النسبية)",
  "dashboard.indicator.guide.section4.signals": "<code>signals</code> - لتحديد إشارات الشراء/البيع (مثل الأسهم والملصقات)",
  "dashboard.indicator.guide.section4.title": "4. متطلبات الإخراج: الإخراج",
