  "dashboard.indicator.guide.section5.title": "5. تكوين المخططات (المخططات)",
  "dashboard.indicator.guide.section6.buy": "سيتم وضع العلامات تلقائيًا أسفل أدنى مستوى لخط K الحالي",
  "dashboard.indicator.guide.section6.calc": "احسب",
  "dashboard.indicator.guide.section6.desc": "تُستخدم <code>signals</code> لتحديد نقاط الشراء/البيع على خطوط K محددة من خلال أيقونات أو نصوص. <strong>ملاحظة:</strong> هذا خاص بعرض الرسم البياني فقط. يستخدم نظام الاختبار الخلفي <code>df['buy_signal']</code> و <code>df['sell_signal']</code>.",
