  "dashboard.indicator.guide.section6.generate": "توليد بيانات الإشارة (التهيئة باستخدام None)",
  "dashboard.indicator.guide.section6.hint": "يتولى النظام عملية تحديد الموقع تلقائيًا.",
  "dashboard.indicator.guide.section6.output": "الناتج",
