  "fastAnalysis.indicatorsProBadge": "PRO",
  "fastAnalysis.indicatorsProSubtitle": "متوافق مع الواجهة الخلفية `MarketDataCollector._calculate_indicators` (النمط السائد): مؤشر القوة النسبية (RSI) (14) مُنعّم باستخدام طريقة وايلدر. مؤشر الماكد (MACD) (12، 26، 9) يستخدم المتوسطات المتحركة الأسية (EMA) المُهيأة للمتوسطات المتحركة البسيطة (SMA) عند الإغلاقات؛ مؤشر التباين (DIF) من الشريط 26 فصاعدًا؛ مؤشر تحليل التباين (DEA) = المتوسط المتحرك الأسي 9 من سلسلة مؤشر التباين (حوالي 34 شريطًا أو أكثر لخط إشارة كامل). المتوسطات المتحركة هي متوسطات متحركة بسيطة. نقطة الارتكاز تستخدم أعلى/أدنى/مركز الشريط السابق. التأرجح = أقصى/أدنى سعر خلال 20 شريطًا. مؤشر بولينجر = المتوسط المتحرك البسيط (20) ± ضعف الانحراف المعياري للسكان؛ المستويات المُجمّعة تستخدم الحد الأعلى/الأسفل لمؤشر بولينجر. مؤشر متوسط المدى الحقيقي (ATR) (14) مُنعّم باستخدام طريقة وايلدر، ومُرتبط بأحدث شريط. راجع ملف docs/INDICATOR_DEFINITIONS_CN.md لمعرفة نسبة الحجم وموضع النطاق.",
