  "user.login.emailInvalid": "تنسيق بريد إلكتروني غير صالح",
  "user.login.emailRequired": "الرجاء إدخال البريد الإلكتروني",
  "user.login.forgot-password": "نسيت كلمة السر؟",
  "user.login.forgotPassword": "هل نسيت كلمة السر؟",
  "user.login.infos": "QuantDinger هي أداة تحليل أسهم متعددة العوامل تعتمد على الذكاء الاصطناعي، ولا تملك مؤهلات استشارية في مجال الاستثمار في الأوراق المالية. جميع نتائج التحليل والتقييمات والآراء المرجعية على المنصة مُولّدة تلقائيًا بواسطة الذكاء الاصطناعي استنادًا إلى بيانات تاريخية، وهي مخصصة لأغراض التعلم والبحث والتبادل الفني فقط، ولا تُشكل أي نصيحة استثمارية أو أساسًا لاتخاذ القرارات. ينطوي الاستثمار في الأسهم على مخاطر السوق، ومخاطر السيولة، ومخاطر السياسات، وغيرها من المخاطر التي قد تؤدي إلى خسائر في رأس المال. يجب على المستخدمين اتخاذ قرارات مستقلة بناءً على قدرتهم على تحمل المخاطر، وتحمل عواقب أي سلوك استثماري ونتائجه باستخدام هذه الأداة. يجب توخي الحذر عند الاستثمار في الأسهم نظرًا لمخاطر السوق.",
  "user.login.legal.agree": "لقد قرأتُ وأوافق على إخلاء المسؤولية القانونية.",
  "user.login.legal.collapse": "إخفاء الإخلاء القانوني",
  "user.login.legal.content": "QuantDinger أداة تحليل أسهم متعددة العوامل تعتمد على الذكاء الاصطناعي، ولا تقدم أي نصائح استثمارية. جميع نتائج التحليل والتقييمات والمراجع مُولّدة بواسطة الذكاء الاصطناعي استنادًا إلى بيانات تاريخية، وهي مخصصة لأغراض التعلم والبحث والتبادل الفني فقط. لا تُعدّ هذه النتائج والتقييمات والمراجع نصيحة استثمارية ولا تُشكّل أساسًا لاتخاذ القرارات. تنطوي استثمارات الأسهم على مخاطر السوق والسيولة والسياسات، مما قد يؤدي إلى خسارة رأس المال. يجب على المستخدمين اتخاذ قرارات مستقلة بناءً على مدى تقبّلهم للمخاطر، وتحمّل عواقب أي سلوك استثماري ونتائجه باستخدام هذه الأداة.",
  "user.login.legal.required": "يرجى قراءة ومراجعة إخلاء المسؤولية القانونية أولاً",
