  "user.login.privacy.collapse": "إخفاء سياسة الخصوصية",
  "user.login.privacy.content": "نحن نُقدّر خصوصيتك وحماية بياناتك. (1) نطاق جمع البيانات: نجمع فقط المعلومات الضرورية لتقديم الخدمة (مثل البريد الإلكتروني، رقم الهاتف، رمز الدولة، عنوان محفظة Web3) وسجلات/بيانات الجهاز المحدودة. (2) الغرض من الاستخدام: تسجيل الدخول إلى الحساب والتحقق الأمني، وتوفير الميزات، واستكشاف الأخطاء وإصلاحها، ومتطلبات الامتثال. (3) التخزين والأمان: يتم تشفير البيانات والتحكم في الوصول إليها لمنع الوصول غير المصرح به أو الكشف عنها أو فقدانها. (4) المشاركة والأطراف الثالثة: لا نشارك البيانات الشخصية مع أطراف ثالثة إلا إذا كان ذلك مطلوبًا بموجب القانون أو لتقديم الخدمة؛ وفي حالة استخدام خدمات أطراف ثالثة (مثل المحافظ، ومزودي خدمات الرسائل النصية القصيرة)، يقتصر المعالجة على الحد الأدنى المطلوب. (5) ملفات تعريف الارتباط/التخزين المحلي: تُستخدم لحالة الجلسة وتسجيل الدخول (مثل الرموز المميزة، وPHPSESSID). يمكنك مسحها أو تقييدها في متصفحك. (6) حقوقك: يمكنك ممارسة حقوق الوصول والتصحيح والحذف وسحب الموافقة وفقًا لما يسمح به القانون. (7) التغييرات والإشعارات: سنقدم إشعارًا واضحًا بالتحديثات. استمرارك في استخدام الخدمة يعني أنك قد قرأت الشروط المحدثة ووافقت عليها. إذا كنت لا توافق، يُرجى التوقف عن استخدام الخدمة والتواصل معنا.",
